import Ajv from 'ajv';
import standaloneCode from 'ajv/dist/standalone/index.js';
import { promises as fs } from 'node:fs';
import { schema } from '../packages/schema/index';
const ajv = new Ajv({
  allErrors: true,
  allowUnionTypes: true,
  code: { source: true, esm: true, lines: true },
});
const check = ajv.compile(schema);
const code = standaloneCode(ajv, check).replaceAll(
  'require("ajv/dist/runtime/ucs2length").default',
  'ucs2length',
);
await fs.writeFile(
  'packages/schema/validator.js',
  '// Generated by scripts/generate-schema.ts. Do not edit.\nconst ucs2length = text => [...text].length;\n' +
    code.trimEnd() +
    '\n',
);
